"use client";

import { useMemo } from "react";
import { GodLights } from "godlights";
import type { SceneConfig, AnimParams } from "godlights";

const animParams: AnimParams = {
  speed: 1,
  angleAmp: 40,
  lengthAmp: 25,
  widthAmp: 15,
  haloAmp: 40,
};

interface GodLightsHeroProps {
  color?: string;
  children?: React.ReactNode;
  className?: string;
}

export function GodLightsHero({
  color = "#a78bfa",
  children,
  className,
}: GodLightsHeroProps) {
  const scene: SceneConfig = useMemo(
    () => ({
      width: 1920,
      height: 1080,
      noise: 8,
      grainSize: 1,
      layers: [
        {
          id: "background",
          type: "background",
          bgType: "solid",
          bgColor: "#06060f",
          bgColor2: "#06060f",
          bgGradientAngle: 180,
        },
        {
          id: "halo-1",
          name: "Glow",
          type: "halo",
          originX: 50,
          originY: -5,
          color,
          intensity: 0.3,
          size: 0.5,
          blendMode: "lighter",
        },
        {
          id: "rays-1",
          name: "Rays",
          type: "rays",
          direction: 180,
          spread: 90,
          originX: 50,
          originY: -5,
          rayCount: 24,
          rayWidth: 70,
          divergence: 1.8,
          rayLength: 1.1,
          colorStart: color,
          colorEnd: color,
          opacity: 0.18,
          blendMode: "screen",
          fadeToTransparent: true,
          blur: 12,
          randomnessWidth: 60,
          randomnessLength: 20,
          randomnessAngle: 15,
          seed: 42,
        },
      ],
    }),
    [color]
  );

  return (
    <section
      className={className}
      style={{ position: "relative", minHeight: "100svh" }}
    >
      <GodLights
        scene={scene}
        animate
        animParams={animParams}
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
        }}
      />
      <div style={{ position: "relative", zIndex: 1 }}>{children}</div>
    </section>
  );
}
